import{_ as l,o as e,c as i,O as r}from"./chunks/framework.2c2d5a61.js";const b=JSON.parse('{"title":"中间件（Redis & 消息队列）","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/06-中间件.md","filePath":"interview/后端/Java/06-中间件.md","lastUpdated":1788851914000}'),t={name:"interview/后端/Java/06-中间件.md"};function h(o,a,d,u,s,n){return e(),i("div",null,a[0]||(a[0]=[r('<h1 id="中间件-redis-消息队列" tabindex="-1">中间件（Redis &amp; 消息队列） <a class="header-anchor" href="#中间件-redis-消息队列" aria-label="Permalink to &quot;中间件（Redis &amp; 消息队列）&quot;">​</a></h1><blockquote><p>常问等级：★★★ 高频必考 / ★★☆ 中频常见 / ★☆☆ 低频了解 深度标准：每个考点讲清「是什么 → 为什么 → 源码关键点 → 追问应对 → 易错点」。</p></blockquote><hr><h2 id="redis-为什么快-单线程模型-★★★" tabindex="-1">Redis 为什么快（单线程模型）★★★ <a class="header-anchor" href="#redis-为什么快-单线程模型-★★★" aria-label="Permalink to &quot;Redis 为什么快（单线程模型）★★★&quot;">​</a></h2><h3 id="为什么单线程还快" tabindex="-1">为什么单线程还快 <a class="header-anchor" href="#为什么单线程还快" aria-label="Permalink to &quot;为什么单线程还快&quot;">​</a></h3><ul><li>纯内存操作，瓶颈在内存/网络而非 CPU。</li><li>单线程避免线程切换、锁竞争开销。</li><li>IO 多路复用（epoll）：一个线程监听多个连接，事件驱动处理。</li><li>高效数据结构（跳表、压缩列表、哈希表）。</li></ul><h3 id="为什么用单线程" tabindex="-1">为什么用单线程 <a class="header-anchor" href="#为什么用单线程" aria-label="Permalink to &quot;为什么用单线程&quot;">​</a></h3><ul><li>Redis 操作主要在内存，单线程足够快且简单；多线程会引入锁与上下文切换。</li></ul><h3 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h3><ul><li>Redis 6.0 引入多线程（仅网络 IO 读写多线程，命令执行仍是单线程），因为网络 IO 成为瓶颈。</li></ul><h3 id="追问应对" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「单线程为什么能高并发？」→ 内存 + IO 多路复用 + 无锁；单线程指命令执行，网络 IO 可多线程。</li><li>「单线程的缺点？」→ 单个慢命令（keys、大 key 删除）会阻塞整个实例，需用 scan/渐进删除。</li></ul><hr><h2 id="redis-数据类型及底层数据结构-★★★" tabindex="-1">Redis 数据类型及底层数据结构 ★★★ <a class="header-anchor" href="#redis-数据类型及底层数据结构-★★★" aria-label="Permalink to &quot;Redis 数据类型及底层数据结构 ★★★&quot;">​</a></h2><h3 id="常用数据类型" tabindex="-1">常用数据类型 <a class="header-anchor" href="#常用数据类型" aria-label="Permalink to &quot;常用数据类型&quot;">​</a></h3><ul><li>String：SDS（简单动态字符串），可存数字/字符串/位图。</li><li>Hash：哈希表 + 压缩列表（小数据）→ listpack（7.0）。</li><li>List：链表/压缩列表，可做消息队列、栈。</li><li>Set：哈希表/intset（整数集合），去重。</li><li>ZSet（有序集合）：跳表 + 哈希表，做排行榜。</li></ul><h3 id="底层结构演进" tabindex="-1">底层结构演进 <a class="header-anchor" href="#底层结构演进" aria-label="Permalink to &quot;底层结构演进&quot;">​</a></h3><ul><li>跳表（skiplist）：ZSet 底层，支持 O(logn) 范围查询和排序。</li><li>压缩列表（ziplist）/listpack：元素少且小的时候用，省内存。</li><li>SDS：比 C 字符串更安全（O(1) 取长度、二进制安全、避免溢出）。</li></ul><h3 id="追问应对-1" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-1" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「ZSet 为什么用跳表不用红黑树？」→ 跳表实现简单、支持范围查询、并发场景友好；红黑树实现复杂。</li><li>「SDS 和 C 字符串区别？」→ SDS 有 len 字段 O(1) 取长度、二进制安全、预分配减少重分配。</li></ul><hr><h2 id="缓存穿透、击穿、雪崩-★★★" tabindex="-1">缓存穿透、击穿、雪崩 ★★★ <a class="header-anchor" href="#缓存穿透、击穿、雪崩-★★★" aria-label="Permalink to &quot;缓存穿透、击穿、雪崩 ★★★&quot;">​</a></h2><h3 id="缓存穿透" tabindex="-1">缓存穿透 <a class="header-anchor" href="#缓存穿透" aria-label="Permalink to &quot;缓存穿透&quot;">​</a></h3><ul><li>查询不存在的数据（key 也不在缓存和 DB），每次都打 DB。</li><li>解决：① 缓存空值（设短过期）；② 布隆过滤器（拦截不存在的 key）；③ 参数校验。</li></ul><h3 id="缓存击穿" tabindex="-1">缓存击穿 <a class="header-anchor" href="#缓存击穿" aria-label="Permalink to &quot;缓存击穿&quot;">​</a></h3><ul><li>某个热点 key 过期瞬间，大量请求同时打 DB。</li><li>解决：① 热点 key 不过期/永不过期；② 互斥锁（只有一个请求回源重建缓存）；③ 逻辑过期。</li></ul><h3 id="缓存雪崩" tabindex="-1">缓存雪崩 <a class="header-anchor" href="#缓存雪崩" aria-label="Permalink to &quot;缓存雪崩&quot;">​</a></h3><ul><li>大量 key 同时过期或 Redis 宕机，请求全打 DB。</li><li>解决：① 过期时间加随机值；② 多级缓存；③ Redis 高可用（集群/哨兵）；④ 限流降级。</li></ul><h3 id="追问应对-2" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-2" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「布隆过滤器原理？」→ 多个哈希函数把 key 映射到位数组，判断「可能存在」或「一定不存在」，可拦截不存在 key；有误判率。</li></ul><hr><h2 id="缓存与数据库一致性-★★★" tabindex="-1">缓存与数据库一致性 ★★★ <a class="header-anchor" href="#缓存与数据库一致性-★★★" aria-label="Permalink to &quot;缓存与数据库一致性 ★★★&quot;">​</a></h2><h3 id="方案" tabindex="-1">方案 <a class="header-anchor" href="#方案" aria-label="Permalink to &quot;方案&quot;">​</a></h3><ul><li>Cache Aside（旁路缓存，主流）：读时先查缓存未命中则查库并回填；写时「先更新数据库，再删除缓存」。</li><li>为什么不先删缓存：先删缓存再更新库，中间可能被别的请求读到旧数据回填缓存，导致不一致。</li></ul><h3 id="保证最终一致" tabindex="-1">保证最终一致 <a class="header-anchor" href="#保证最终一致" aria-label="Permalink to &quot;保证最终一致&quot;">​</a></h3><ul><li>延时双删：更新库 → 删缓存 → 延迟再删一次。</li><li>订阅 binlog（Canal）异步删缓存。</li><li>事务消息/重试机制。</li></ul><h3 id="追问应对-3" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-3" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么是删除缓存而不是更新缓存？」→ 删除更简单、避免并发更新顺序问题；懒加载避免写不常读的数据。</li><li>「强一致性怎么保证？」→ 缓存场景通常接受最终一致；强一致可加分布式锁或读写都走库。</li></ul><hr><h2 id="redis-持久化-rdb-与-aof-★★★" tabindex="-1">Redis 持久化：RDB 与 AOF ★★★ <a class="header-anchor" href="#redis-持久化-rdb-与-aof-★★★" aria-label="Permalink to &quot;Redis 持久化：RDB 与 AOF ★★★&quot;">​</a></h2><h3 id="rdb-快照" tabindex="-1">RDB（快照） <a class="header-anchor" href="#rdb-快照" aria-label="Permalink to &quot;RDB（快照）&quot;">​</a></h3><ul><li>定时把内存数据快照写入磁盘（fork 子进程 + 写时复制）。</li><li>优点：文件小、恢复快、对性能影响小；缺点：两次快照间数据可能丢失。</li><li>触发：<code>save</code>（阻塞）、<code>bgsave</code>（fork 子进程）、配置 <code>save 900 1</code>。</li></ul><h3 id="aof-追加日志" tabindex="-1">AOF（追加日志） <a class="header-anchor" href="#aof-追加日志" aria-label="Permalink to &quot;AOF（追加日志）&quot;">​</a></h3><ul><li>记录每次写命令，追加写入。</li><li>策略：always（每条刷盘，最安全慢）、everysec（每秒，默认折中）、no（OS 决定）。</li><li>优点：数据更完整；缺点：文件大、恢复慢；AOF 重写压缩。</li></ul><h3 id="混合持久化" tabindex="-1">混合持久化 <a class="header-anchor" href="#混合持久化" aria-label="Permalink to &quot;混合持久化&quot;">​</a></h3><ul><li>Redis 4.0+：RDB 快照 + 增量 AOF，兼顾恢复速度与数据完整性。</li></ul><h3 id="追问应对-4" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-4" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「生产怎么选？」→ 数据不能丢用 AOF everysec，或 RDB + AOF 混合；能容忍少量丢失可只用 RDB。</li><li>「bgsave 为什么 fork？」→ 子进程写时复制，主进程继续服务，不阻塞。</li></ul><hr><h2 id="redis-过期删除策略与内存淘汰-★★★" tabindex="-1">Redis 过期删除策略与内存淘汰 ★★★ <a class="header-anchor" href="#redis-过期删除策略与内存淘汰-★★★" aria-label="Permalink to &quot;Redis 过期删除策略与内存淘汰 ★★★&quot;">​</a></h2><h3 id="过期删除" tabindex="-1">过期删除 <a class="header-anchor" href="#过期删除" aria-label="Permalink to &quot;过期删除&quot;">​</a></h3><ul><li>惰性删除：访问 key 时才检查是否过期。</li><li>定期删除：周期性随机抽样一批 key 检查删除。</li><li>二者结合（Redis 实际采用）：平衡 CPU 与内存。</li></ul><h3 id="内存淘汰策略-内存满时" tabindex="-1">内存淘汰策略（内存满时） <a class="header-anchor" href="#内存淘汰策略-内存满时" aria-label="Permalink to &quot;内存淘汰策略（内存满时）&quot;">​</a></h3><ul><li>noeviction：不淘汰，写入报错。</li><li>allkeys-lru：所有 key 里淘汰最久未用（推荐）。</li><li>volatile-lru：只在有过期时间的 key 里淘汰。</li><li>allkeys-random / volatile-random：随机。</li><li>volatile-ttl：淘汰最早过期的。</li><li>allkeys-lfu / volatile-lfu：淘汰最不常用（LFU）。</li></ul><h3 id="追问应对-5" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-5" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么不只靠惰性删除？」→ 惰性删除下长期不访问的过期 key 会占内存，需定期删除兜底。</li><li>「LRU 和 LFU 区别？」→ LRU 按最近访问时间，LFU 按访问频率；LFU 更抗「偶发热点」。</li></ul><hr><h2 id="redis-分布式锁-redisson-★★★" tabindex="-1">Redis 分布式锁（Redisson）★★★ <a class="header-anchor" href="#redis-分布式锁-redisson-★★★" aria-label="Permalink to &quot;Redis 分布式锁（Redisson）★★★&quot;">​</a></h2><h3 id="基本实现" tabindex="-1">基本实现 <a class="header-anchor" href="#基本实现" aria-label="Permalink to &quot;基本实现&quot;">​</a></h3><ul><li>SET key value NX EX 秒：原子加锁 + 设过期时间。</li><li>value 用唯一标识（UUID + 线程 id），释放时校验 value 一致再删除（防误删他人锁）。</li></ul><h3 id="为什么用-lua" tabindex="-1">为什么用 Lua <a class="header-anchor" href="#为什么用-lua" aria-label="Permalink to &quot;为什么用 Lua&quot;">​</a></h3><ul><li>「判断 value + 删除」需原子，用 Lua 脚本保证（避免释放锁时误删）。</li></ul><h3 id="关键问题" tabindex="-1">关键问题 <a class="header-anchor" href="#关键问题" aria-label="Permalink to &quot;关键问题&quot;">​</a></h3><ul><li>锁续期：业务执行超过锁过期时间会提前释放，Redisson 用看门狗（Watch Dog）自动续期。</li><li>锁重入：Redisson 支持可重入。</li><li>主从切换丢锁：主节点宕机锁丢失，用 RedLock（多节点）缓解，但 RedLock 也有争议。</li></ul><h3 id="追问应对-6" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-6" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「SET NX 为什么不安全？」→ 可能业务未完成锁就过期；需续期或设足够长过期 + 看门狗。</li><li>「释放锁为什么要校验 value？」→ 防止 A 线程删了 B 线程的锁。</li></ul><hr><h2 id="redis-集群-主从、哨兵、cluster-★★★" tabindex="-1">Redis 集群：主从、哨兵、Cluster ★★★ <a class="header-anchor" href="#redis-集群-主从、哨兵、cluster-★★★" aria-label="Permalink to &quot;Redis 集群：主从、哨兵、Cluster ★★★&quot;">​</a></h2><h3 id="主从复制" tabindex="-1">主从复制 <a class="header-anchor" href="#主从复制" aria-label="Permalink to &quot;主从复制&quot;">​</a></h3><ul><li>从节点复制主节点数据，实现读写分离和备份；主写从读。</li></ul><h3 id="哨兵-sentinel" tabindex="-1">哨兵（Sentinel） <a class="header-anchor" href="#哨兵-sentinel" aria-label="Permalink to &quot;哨兵（Sentinel）&quot;">​</a></h3><ul><li>监控主从节点，主节点宕机自动选举新主（故障转移），高可用。</li></ul><h3 id="cluster-集群" tabindex="-1">Cluster（集群） <a class="header-anchor" href="#cluster-集群" aria-label="Permalink to &quot;Cluster（集群）&quot;">​</a></h3><ul><li>数据分片（16384 个 hash slot 分配到不同节点），水平扩展。</li><li>通过 <code>CRC16(key) % 16384</code> 定位槽和节点。</li><li>支持故障转移、客户端重定向（MOVED/ASK）。</li></ul><h3 id="追问应对-7" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-7" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「哨兵和集群区别？」→ 哨兵解决「高可用」（一个主），集群解决「扩展性」（多个主分片），集群自带高可用。</li><li>「为什么是 16384 个槽？」→ 16384 足够分片且心跳包小、槽位图传输开销低。</li></ul><hr><h2 id="缓存预热、缓存降级、热点-key-★★☆" tabindex="-1">缓存预热、缓存降级、热点 key ★★☆ <a class="header-anchor" href="#缓存预热、缓存降级、热点-key-★★☆" aria-label="Permalink to &quot;缓存预热、缓存降级、热点 key ★★☆&quot;">​</a></h2><ul><li>缓存预热：启动时提前加载热点数据到缓存，避免冷启动击穿。</li><li>缓存降级：缓存/DB 压力大时，降级为兜底数据/限流。</li><li>热点 key：发现访问集中的 key，可做本地缓存（如 Caffeine）+ Redis 二级缓存。</li></ul><hr><h2 id="为什么用消息队列-作用-★★★" tabindex="-1">为什么用消息队列，作用 ★★★ <a class="header-anchor" href="#为什么用消息队列-作用-★★★" aria-label="Permalink to &quot;为什么用消息队列，作用 ★★★&quot;">​</a></h2><ul><li>解耦：生产者和消费者不直接依赖，通过 MQ 中转。</li><li>异步：非核心流程异步处理，提升响应速度。</li><li>削峰：高峰期请求入队，消费者按自身能力消费，保护下游。</li><li>缺点：系统复杂度增加、一致性问题（消息丢失/重复）、可用性依赖 MQ。</li></ul><h3 id="追问应对-8" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-8" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「什么时候不该用 MQ？」→ 同步强一致、低延迟、简单调用场景，别为了用而用。</li></ul><hr><h2 id="消息丢失怎么解决-★★★" tabindex="-1">消息丢失怎么解决 ★★★ <a class="header-anchor" href="#消息丢失怎么解决-★★★" aria-label="Permalink to &quot;消息丢失怎么解决 ★★★&quot;">​</a></h2><h3 id="三个环节" tabindex="-1">三个环节 <a class="header-anchor" href="#三个环节" aria-label="Permalink to &quot;三个环节&quot;">​</a></h3><ol><li>生产者丢失：发送失败/网络问题 → 发送确认机制（ack）、事务消息、重试。</li><li>MQ 丢失：消息未持久化 → 开启持久化（刷盘）、同步复制（主从）。</li><li>消费者丢失：消费后未提交就挂 → 手动 ack，处理完成再确认。</li></ol><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><ul><li>端到端：生产确认 + MQ 持久化 + 消费手动 ack，保证至少一次投递。</li></ul><h3 id="追问应对-9" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-9" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「怎么保证消息不丢？」→ 三层：producer confirm、broker 持久化 + 复制、consumer 手动 ack。</li></ul><hr><h2 id="消息重复消费怎么解决-★★★" tabindex="-1">消息重复消费怎么解决 ★★★ <a class="header-anchor" href="#消息重复消费怎么解决-★★★" aria-label="Permalink to &quot;消息重复消费怎么解决 ★★★&quot;">​</a></h2><h3 id="为什么重复" tabindex="-1">为什么重复 <a class="header-anchor" href="#为什么重复" aria-label="Permalink to &quot;为什么重复&quot;">​</a></h3><ul><li>至少一次投递 + 网络重试/超时重发，天然可能重复。</li></ul><h3 id="解决" tabindex="-1">解决 <a class="header-anchor" href="#解决" aria-label="Permalink to &quot;解决&quot;">​</a></h3><ul><li>幂等：消费端做幂等处理。 <ul><li>唯一键（数据库唯一索引 + 插入冲突忽略）。</li><li>Redis setnx 记录已处理的消息 id。</li><li>状态机（订单状态已支付则跳过）。</li></ul></li></ul><h3 id="追问应对-10" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-10" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「MQ 能保证不重复吗？」→ 不能（除非恰好一次语义，代价大），业务端必须幂等。</li></ul><hr><h2 id="消息顺序消费-★★☆" tabindex="-1">消息顺序消费 ★★☆ <a class="header-anchor" href="#消息顺序消费-★★☆" aria-label="Permalink to &quot;消息顺序消费 ★★☆&quot;">​</a></h2><ul><li>保证顺序：单分区/单队列（同一业务消息发到同一分区/队列），消费者单线程消费。</li><li>RocketMQ：顺序消息按 MessageQueue 顺序；Kafka：同一 partition 内有序。</li><li>若要求全局有序，只能一个队列 + 单消费者，牺牲并发。</li></ul><h3 id="追问应对-11" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-11" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「全局有序和局部有序？」→ 全局有序性能差（单队列）；一般只需保证「同一业务 key（如订单）内有序」。</li></ul><hr><h2 id="消息积压怎么解决-★★☆" tabindex="-1">消息积压怎么解决 ★★☆ <a class="header-anchor" href="#消息积压怎么解决-★★☆" aria-label="Permalink to &quot;消息积压怎么解决 ★★☆&quot;">​</a></h2><ul><li>增加消费者实例、消费者并发度。</li><li>优化消费逻辑（批处理、减少 IO）。</li><li>临时新建 topic 分流、降级非核心消息。</li><li>检查消费者是否故障/慢。</li></ul><hr><h2 id="死信队列、延迟消息-★★☆" tabindex="-1">死信队列、延迟消息 ★★☆ <a class="header-anchor" href="#死信队列、延迟消息-★★☆" aria-label="Permalink to &quot;死信队列、延迟消息 ★★☆&quot;">​</a></h2><ul><li>死信队列：消费失败达重试上限、消息过期、队列满时进入死信队列，用于人工处理/告警。</li><li>延迟消息：消息延迟一定时间后才投递（RocketMQ 延迟等级、RabbitMQ 死信 + TTL 模拟、Kafka 需额外实现）。</li><li>应用：订单超时未支付自动取消。</li></ul><hr><h2 id="kafka、rocketmq、rabbitmq-对比-★★☆" tabindex="-1">Kafka、RocketMQ、RabbitMQ 对比 ★★☆ <a class="header-anchor" href="#kafka、rocketmq、rabbitmq-对比-★★☆" aria-label="Permalink to &quot;Kafka、RocketMQ、RabbitMQ 对比 ★★☆&quot;">​</a></h2><table><thead><tr><th>维度</th><th>Kafka</th><th>RocketMQ</th><th>RabbitMQ</th></tr></thead><tbody><tr><td>定位</td><td>大数据日志/流</td><td>业务消息/事务</td><td>通用消息</td></tr><tr><td>吞吐</td><td>极高</td><td>高</td><td>中</td></tr><tr><td>顺序</td><td>分区内有序</td><td>队列内有序/全局顺序</td><td>一般</td></tr><tr><td>事务消息</td><td>较弱</td><td>支持</td><td>支持（较弱）</td></tr><tr><td>延迟消息</td><td>需自实现</td><td>原生支持</td><td>TTL+死信模拟</td></tr><tr><td>协议</td><td>自定义</td><td>自定义</td><td>AMQP</td></tr><tr><td>语言</td><td>Java/Scala</td><td>Java</td><td>Erlang</td></tr></tbody></table><ul><li>选型：日志/大数据流用 Kafka；电商/金融业务消息、事务消息用 RocketMQ；一般企业、协议标准化用 RabbitMQ。</li></ul><hr><h2 id="缓存设计模式-★★★" tabindex="-1">缓存设计模式 ★★★ <a class="header-anchor" href="#缓存设计模式-★★★" aria-label="Permalink to &quot;缓存设计模式 ★★★&quot;">​</a></h2><h3 id="cache-aside-旁路缓存-最常用" tabindex="-1">Cache Aside（旁路缓存，最常用） <a class="header-anchor" href="#cache-aside-旁路缓存-最常用" aria-label="Permalink to &quot;Cache Aside（旁路缓存，最常用）&quot;">​</a></h3><ul><li>读：先查缓存，未命中则查库并回填缓存。</li><li>写：先更新数据库，再删除缓存（不是更新缓存）。</li><li>优点：简单、缓存与库解耦；缺点：存在短暂不一致窗口。</li></ul><h3 id="read-through-读穿透" tabindex="-1">Read Through（读穿透） <a class="header-anchor" href="#read-through-读穿透" aria-label="Permalink to &quot;Read Through（读穿透）&quot;">​</a></h3><ul><li>缓存层自己负责查库回填（应用不感知数据库），读逻辑封装在缓存组件里。</li></ul><h3 id="write-through-写穿透" tabindex="-1">Write Through（写穿透） <a class="header-anchor" href="#write-through-写穿透" aria-label="Permalink to &quot;Write Through（写穿透）&quot;">​</a></h3><ul><li>写时同时更新缓存和数据库，保证缓存与库一致，但写开销大（每次写都更新缓存，即使数据不常读）。</li></ul><h3 id="write-behind-write-back-写回" tabindex="-1">Write Behind / Write Back（写回） <a class="header-anchor" href="#write-behind-write-back-写回" aria-label="Permalink to &quot;Write Behind / Write Back（写回）&quot;">​</a></h3><ul><li>写时只更新缓存，异步批量刷到数据库；性能最高但一致性最弱，缓存挂了可能丢数据。</li></ul><h3 id="追问应对-12" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-12" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么 Cache Aside 写是删缓存而不是更新？」→ 删除更简单、避免并发更新顺序问题、懒加载避免写不常读的数据。</li><li>「Write Through 和 Write Back 区别？」→ Write Through 同步写库（一致性好、慢），Write Back 异步批量写库（快、可能丢数据）。</li></ul><hr><h2 id="redis-pipeline-的好处-★★☆" tabindex="-1">Redis Pipeline 的好处 ★★☆ <a class="header-anchor" href="#redis-pipeline-的好处-★★☆" aria-label="Permalink to &quot;Redis Pipeline 的好处 ★★☆&quot;">​</a></h2><h3 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><ul><li>把多条命令打包一次性发给 Redis，减少「每条命令一次网络往返（RTT）」的开销。</li></ul><h3 id="为什么快" tabindex="-1">为什么快 <a class="header-anchor" href="#为什么快" aria-label="Permalink to &quot;为什么快&quot;">​</a></h3><ul><li>Redis 处理单条命令很快，瓶颈常在网络 RTT；pipeline 把 N 次 RTT 变成 1 次，批量命令执行仍是单线程顺序执行。</li></ul><h3 id="注意-1" tabindex="-1">注意 <a class="header-anchor" href="#注意-1" aria-label="Permalink to &quot;注意&quot;">​</a></h3><ul><li>Pipeline 不是原子操作（命令间可能被其他客户端命令穿插，除非用事务 MULTI/EXEC）。</li><li>与传统「批量命令（mget/mset）」区别：mget/mset 是单条命令操作多个 key（原子），pipeline 是多条命令打包（非原子）。</li></ul><h3 id="追问应对-13" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-13" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「Pipeline 和事务区别？」→ Pipeline 只减少 RTT、非原子；事务（MULTI/EXEC）保证原子但不减少 RTT（可结合使用）。</li></ul><hr><h2 id="redis-和-hashmap-的区别-★★☆" tabindex="-1">Redis 和 HashMap 的区别 ★★☆ <a class="header-anchor" href="#redis-和-hashmap-的区别-★★☆" aria-label="Permalink to &quot;Redis 和 HashMap 的区别 ★★☆&quot;">​</a></h2><ul><li>Redis 是「独立的分布式缓存服务」，基于网络通信，支持持久化、集群、过期、多种数据类型、跨进程/跨机器共享。</li><li>HashMap 是「JVM 内的本地数据结构」，仅单机单进程内有效，无持久化、无网络、GC 管理内存。</li><li>对比维度：Redis 容量大（可集群）、可共享、有持久化和淘汰；HashMap 速度快（内存直读、无网络）但受单机内存限制、重启丢失。</li></ul><h3 id="追问应对-14" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-14" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么有了 HashMap 还要 Redis？」→ HashMap 无法跨实例共享、无法持久化、容量受单机限制；Redis 解决分布式缓存/共享/持久化。</li></ul><hr><h2 id="什么时候选-redis-什么时候选本地缓存-caffeine-memcached-★★☆" tabindex="-1">什么时候选 Redis，什么时候选本地缓存（Caffeine）/ Memcached ★★☆ <a class="header-anchor" href="#什么时候选-redis-什么时候选本地缓存-caffeine-memcached-★★☆" aria-label="Permalink to &quot;什么时候选 Redis，什么时候选本地缓存（Caffeine）/ Memcached ★★☆&quot;">​</a></h2><ul><li>Redis：需要跨服务/跨实例共享、持久化、丰富数据结构、分布式场景。</li><li>本地缓存（Caffeine/Guava Cache）：单机内热点数据、要求纳秒级低延迟、无需跨实例共享（如配置、字典）。</li><li>常见组合：本地缓存 + Redis 二级缓存（本地缓存做第一层，Redis 做第二层，减少网络开销）。</li><li>Memcached vs Redis：Memcached 只支持简单 KV、无持久化、多线程、纯内存；Redis 数据结构丰富、支持持久化、单线程（6.0 网络多线程）。现在多数场景选 Redis。</li></ul><h3 id="追问应对-15" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-15" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「Redis 和本地缓存怎么配合？」→ 本地缓存做一级（快、容量小），Redis 做二级（共享、容量大），注意两级缓存的一致性问题。</li></ul><hr><h2 id="redis-内存用完了会发生什么-★★★" tabindex="-1">Redis 内存用完了会发生什么 ★★★ <a class="header-anchor" href="#redis-内存用完了会发生什么-★★★" aria-label="Permalink to &quot;Redis 内存用完了会发生什么 ★★★&quot;">​</a></h2><h3 id="结果" tabindex="-1">结果 <a class="header-anchor" href="#结果" aria-label="Permalink to &quot;结果&quot;">​</a></h3><ul><li>取决于「内存淘汰策略（maxmemory-policy）」： <ol><li>默认 <code>noeviction</code>：内存满后，写操作（SET 等会新增内存的命令）直接报错 <code>OOM command not allowed</code>，但读操作、删除操作仍可用。</li><li><code>allkeys-lru</code> / <code>volatile-lru</code> 等：内存满时按策略淘汰 key，腾出空间，写操作继续成功。</li></ol></li><li>注意：不管哪种策略，内存到 <code>maxmemory</code> 上限就会触发淘汰或报错；没有配置 <code>maxmemory</code> 时，Redis 会一直吃内存直到系统内存耗尽，可能被 OS OOM Killer 杀掉。</li></ul><h3 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h3><ul><li><code>maxmemory</code> 设置最大内存，<code>maxmemory-policy</code> 设置淘汰策略。</li></ul><h3 id="追问应对-16" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-16" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「生产怎么配？」→ 一定设置 <code>maxmemory</code> + 合适的淘汰策略（一般 <code>allkeys-lru</code>），避免内存打爆系统。</li></ul><hr><h2 id="mq-部署单机还是集群、高可用怎么保证-★★★" tabindex="-1">MQ 部署单机还是集群、高可用怎么保证 ★★★ <a class="header-anchor" href="#mq-部署单机还是集群、高可用怎么保证-★★★" aria-label="Permalink to &quot;MQ 部署单机还是集群、高可用怎么保证 ★★★&quot;">​</a></h2><h3 id="结论-1" tabindex="-1">结论 <a class="header-anchor" href="#结论-1" aria-label="Permalink to &quot;结论&quot;">​</a></h3><ul><li>生产必须集群部署，单机有单点故障。</li></ul><h3 id="kafka-高可用" tabindex="-1">Kafka 高可用 <a class="header-anchor" href="#kafka-高可用" aria-label="Permalink to &quot;Kafka 高可用&quot;">​</a></h3><ul><li>多副本机制：每个 partition 有多个 replica（leader + follower），leader 挂掉自动选举新 leader，保证消息不丢、服务可用。</li></ul><h3 id="rocketmq-高可用" tabindex="-1">RocketMQ 高可用 <a class="header-anchor" href="#rocketmq-高可用" aria-label="Permalink to &quot;RocketMQ 高可用&quot;">​</a></h3><ul><li>主从复制 + NameServer 集群；Broker 主从同步，主挂自动切换（配合 Dledger 实现主从自动切换）。</li></ul><h3 id="rabbitmq-高可用" tabindex="-1">RabbitMQ 高可用 <a class="header-anchor" href="#rabbitmq-高可用" aria-label="Permalink to &quot;RabbitMQ 高可用&quot;">​</a></h3><ul><li>镜像队列（mirrored queue）：队列在多个节点间镜像，主节点挂掉从镜像节点接管；或 Quorum Queue（仲裁队列，Raft 协议）。</li></ul><h3 id="追问应对-17" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-17" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么集群能保证高可用？」→ 数据多副本 + 故障自动切换（选举新主），单节点挂了不影响整体。</li></ul><hr><h2 id="如何解决消息队列的延时、过期失效问题-★★★" tabindex="-1">如何解决消息队列的延时、过期失效问题 ★★★ <a class="header-anchor" href="#如何解决消息队列的延时、过期失效问题-★★★" aria-label="Permalink to &quot;如何解决消息队列的延时、过期失效问题 ★★★&quot;">​</a></h2><h3 id="延迟消息" tabindex="-1">延迟消息 <a class="header-anchor" href="#延迟消息" aria-label="Permalink to &quot;延迟消息&quot;">​</a></h3><ul><li>定时/延迟投递：RocketMQ 延迟等级、RabbitMQ 死信 + TTL 模拟、Kafka 需自实现（时间轮）。</li></ul><h3 id="消息过期失效" tabindex="-1">消息过期失效 <a class="header-anchor" href="#消息过期失效" aria-label="Permalink to &quot;消息过期失效&quot;">​</a></h3><ul><li>问题：消息设置了 TTL 却一直没被消费，过期进入死信队列，导致「本来该处理的业务没处理」。</li><li>解决： <ol><li>死信队列兜底：消费死信队列做补偿/告警。</li><li>监控积压：告警并及时扩容消费者。</li><li>避免设过短的 TTL；确保消费者正常消费。</li></ol></li></ul><h3 id="消息积压" tabindex="-1">消息积压 <a class="header-anchor" href="#消息积压" aria-label="Permalink to &quot;消息积压&quot;">​</a></h3><ul><li>增加消费者、提升并发、临时分流、优化消费逻辑（见消息积压部分）。</li></ul><h3 id="追问应对-18" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-18" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「消息积压导致大量过期怎么办？」→ 紧急扩容消费者 + 提高消费速度 + 死信补偿 + 修复消费瓶颈。</li></ul><hr><h2 id="如果让你写一个消息队列-如何架构-★★★" tabindex="-1">如果让你写一个消息队列，如何架构 ★★★ <a class="header-anchor" href="#如果让你写一个消息队列-如何架构-★★★" aria-label="Permalink to &quot;如果让你写一个消息队列，如何架构 ★★★&quot;">​</a></h2><h3 id="核心模块" tabindex="-1">核心模块 <a class="header-anchor" href="#核心模块" aria-label="Permalink to &quot;核心模块&quot;">​</a></h3><ol><li>存储：消息持久化（顺序写日志文件，如 commit log）。</li><li>分区/队列：支持多个 topic 分区，实现并行与顺序。</li><li>网络通信：高性能网络框架（Netty），生产者/消费者协议。</li><li>消息投递：push/pull 模型、消费位移（offset）管理。</li><li>高可用：多副本、主从同步、故障转移。</li><li>可靠投递：ack 机制、重试、持久化。</li></ol><h3 id="关键设计点" tabindex="-1">关键设计点 <a class="header-anchor" href="#关键设计点" aria-label="Permalink to &quot;关键设计点&quot;">​</a></h3><ul><li>顺序写 + 零拷贝提升吞吐。</li><li>消费位移记录支持重复消费与进度管理。</li><li>副本机制保证不丢消息。</li></ul><h3 id="追问应对-19" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-19" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么 Kafka 用顺序写？」→ 顺序写磁盘接近内存速度（相比随机写快很多），配合页缓存 + 零拷贝大幅提升吞吐。</li></ul><hr><h2 id="redis-慢查询怎么找、怎么优化-★★★" tabindex="-1">Redis 慢查询怎么找、怎么优化 ★★★ <a class="header-anchor" href="#redis-慢查询怎么找、怎么优化-★★★" aria-label="Permalink to &quot;Redis 慢查询怎么找、怎么优化 ★★★&quot;">​</a></h2><h3 id="找慢查询" tabindex="-1">找慢查询 <a class="header-anchor" href="#找慢查询" aria-label="Permalink to &quot;找慢查询&quot;">​</a></h3><ul><li>配置：<code>slowlog-log-slower-than</code>（阈值，微秒）、<code>slowlog-max-len</code>（保留条数）。</li><li>查看：<code>slowlog get [n]</code> 查看最近慢命令。</li><li>也可用 <code>latency monitor</code>、<code>redis-cli --stat</code>、<code>INFO commandstats</code> 观察。</li></ul><h3 id="优化方向" tabindex="-1">优化方向 <a class="header-anchor" href="#优化方向" aria-label="Permalink to &quot;优化方向&quot;">​</a></h3><ol><li>避免慢命令：<code>keys *</code>（改 <code>scan</code>）、<code>hgetall</code> 大 key、<code>smembers</code> 大集合、<code>sort</code>。</li><li>大 key 拆分：大 value 拆成多个小 key，或用 hash 分片。</li><li>避免阻塞命令：删除大 key 用 <code>unlink</code>（异步删除）而非 <code>del</code>。</li><li>合理数据结构：用合适类型减少内存与命令开销。</li><li>用 pipeline 批量、减少 RTT。</li><li>持久化策略调优（AOF 重写、RDB 触发时机）。</li></ol><h3 id="追问应对-20" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-20" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「Redis 为什么单线程下还有慢命令？」→ 单命令执行是串行的，一个慢命令（如大 key 遍历）会阻塞后续所有命令。</li></ul><hr><h2 id="redis-性能优化-★★★" tabindex="-1">Redis 性能优化 ★★★ <a class="header-anchor" href="#redis-性能优化-★★★" aria-label="Permalink to &quot;Redis 性能优化 ★★★&quot;">​</a></h2><ul><li>内存：合理淘汰策略、压缩编码（ziplist/listpack）、控制大 key。</li><li>命令：避免 O(n) 慢命令、用 scan、批量用 pipeline/mget。</li><li>网络：多线程 IO（6.0）、pipeline 减少 RTT。</li><li>持久化：RDB/AOF 平衡，AOF 用 everysec、及时重写。</li><li>架构：主从读写分离、Cluster 分片、热点 key 本地缓存。</li><li>参数：maxmemory、连接池大小、超时配置。</li></ul><h3 id="追问应对-21" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-21" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「怎么发现热点 key？」→ 监控访问频率（<code>redis-cli --hotkeys</code> 或监控统计），热点数据做本地缓存/分片分流。</li></ul>',198)]))}const q=l(t,[["render",h]]);export{b as __pageData,q as default};
